                "description": "The session's title, as you started it.",
                "type": "string"
              }
            },
            "required": [
              "session",
              "message"
            ],
            "type": "object"
          }
        },
        {
          "tool_name": "sessions__read_session",
          "description": "Read another Newen session the user mentioned: its title, folder and conversation so far (the people's messages and the agent's replies, the latest last). Read-only.",
          "score": 2.354259729385376,
          "input_schema": {
            "properties": {
              "session_id": {
                "type": "integer"
              }
            },
            "required": [
              "session_id"
            ],
            "type": "object"
          }
        }
      ]
    },
    {
      "server": "browser",
      "tools": [
        {
          "tool_name": "browser__preview_list",
          "description": "The dev servers started with preview_start: their ids, names, addresses and whether they run.",
          "score": 2.669722557067871,
          "input_schema": {
            "properties": {},
            "type": "object"
          }
        },
        {
          "tool_name": "browser__browser_batch",
          "description": "Run up to 25 of these tools one after another, stopping at the first that fails: a list of {\"tool\": name, \"input\": {...}}. For steps whose outcome you do not need to see in between.",
